{
  "case_id": "C02",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "Hook: worn-out cells",
      "narration": "As bodies age, some cells stop dividing but refuse to die. These 'senescent' cells build up in our tissues and leak signals that irritate the cells around them.",
      "on_screen": "Animated tissue: normal cells dividing, a few turning grey and emitting signal particles",
      "claim_refs": ["SYN-C02:background"]
    },
    {
      "beat": "The experiment",
      "narration": "Researchers gave 96 elderly mice, two years old, a drug pair called dasatinib and quercetin, or a dummy treatment. Dosing ran three days every fortnight for sixteen weeks. Mice were randomly assigned, and the scientists measuring the results didn't know which was which.",
      "on_screen": "Two mouse groups splitting from a randomiser; calendar showing 3-day pulses every 14 days",
      "claim_refs": ["SYN-C02:design", "SYN-C02:methods"]
    },
    {
      "beat": "What improved",
      "narration": "In fat tissue, senescent cells dropped by 41 percent. Treated mice lasted 22 percent longer on a rotating rod, a balance test. And median remaining lifespan rose from about 21 to 27 weeks.",
      "on_screen": "Three result cards: -41% cell burden, +22% rotarod, 21.4 to 26.9 weeks survival",
      "claim_refs": ["SYN-C02:result:p16-burden", "SYN-C02:result:rotarod", "SYN-C02:result:lifespan"]
    },
    {
      "beat": "What didn't",
      "narration": "But grip strength didn't budge, and only fat tissue was checked, in one mouse strain at one age.",
      "on_screen": "Grip-strength card marked 'no change'; limitations list",
      "claim_refs": ["SYN-C02:result:grip-strength", "SYN-C02:limitations"]
    },
    {
      "beat": "Takeaway",
      "narration": "So: promising, and these drugs already exist. But this is mice, not people. Human trials will have to say whether clearing old cells does anything for us.",
      "on_screen": "Mouse icon with arrow to human icon and a question mark",
      "claim_refs": ["SYN-C02:discussion", "SYN-C02:conclusion"]
    }
  ]
}
